#!/usr/bin/env python3
"""Generate 500 AURA persona cases into examples/persona_cases/.

The produced JSONL files are embedded into the Rust binary at compile time via
`include_dir!`, so they work identically on Linux desktop and Android without
any runtime path hunting.  Every hardcoded user-facing string that used to live in
src/ is mirrored here as a retrievable, editable example.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "examples" / "persona_cases"


def case(category, type_, prompt, response, tone, memory_rule="none", priority=5, match_mode="contains"):
    return {
        "category": category,
        "type": type_,
        "prompt": prompt,
        "priority": priority,
        "match_mode": match_mode,
        "expected_tone": tone,
        "memory_rule": memory_rule,
        "reference_response": response,
    }


def write_jsonl(filename, cases):
    path = OUT / filename
    with open(path, "w", encoding="utf-8") as f:
        for c in cases:
            f.write(json.dumps(c, ensure_ascii=False) + "\n")
    print(f"wrote {len(cases)} cases to {path}")


